<?php
namespace Tests;
use App\Services\{SalonStore,CalendarImport,MarketingConnections,MarketingCampaigns,ContactImport};
use Illuminate\Support\Facades\{Artisan,DB,Http};
use Carbon\CarbonImmutable as Time;
class ImportFollowupTest extends \Illuminate\Foundation\Testing\TestCase
{
 public function createApplication(){$app=require __DIR__.'/../bootstrap/app.php';$app->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $app;}
 protected function setUp():void{parent::setUp();Artisan::call('migrate',['--force'=>true]);$s=SalonStore::initial();$s['subscription']=['plan'=>'pro','status'=>'active'];$s['settings']['openingTime']='00:00';$s['settings']['closingTime']='23:59';DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode($s)]);$this->withSession(['admin'=>true,'provider_id'=>1]);Http::preventStrayRequests();}
 protected function tearDown():void{Time::setTestNow();parent::tearDown();}
 public function test_import_normalization_and_unified_prompt_dismissal():void{
  foreach(['+36 [30] 123-4567','0036 (30) 123 4567','06-30/123-4567'] as $raw)$this->assertSame('06301234567',ContactImport::phone($raw));$this->assertSame('+442012345678',ContactImport::phone('+44 (20) 1234-5678'));
  $this->postJson('/api/contact-import/dismiss',['source'=>'all'])->assertOk();$this->getJson('/api/contact-import/status')->assertJsonStructure(['prompts'=>['all'=>['snoozedUntil']]]);$this->postJson('/api/contact-import/dismiss',['source'=>'none'])->assertOk();$this->getJson('/api/contact-import/status')->assertJsonPath('prompts.all.disabled',true);
 }
 public function test_calendar_block_import_is_idempotent_and_never_creates_contacts_without_opt_in():void{
  $event=CalendarImport::event(['id'=>'e1','summary'=>'Kati festés','description'=>'Telefon: +36 30 123-4567, e-mail kati@example.com','start'=>['dateTime'=>'2036-06-01T10:00:00+02:00'],'end'=>['dateTime'=>'2036-06-01T11:00:00+02:00']]);$this->assertSame('06301234567',$event['phone']);$this->assertSame('kati@example.com',$event['email']);
  $choice=['index'=>0,'mode'=>'block','staff'=>'anna','contact'=>false,'name'=>'Kati','phone'=>'06301234567','email'=>'kati@example.com'];$result=app(SalonStore::class)->mutate(fn(&$s)=>CalendarImport::apply($s,[$event],[$choice],'calendar'),false);$this->assertSame(1,$result['blocks']);$s=app(SalonStore::class)->read();$this->assertCount(0,$s['clients']);$this->assertSame('10:00',$s['availability']['blocks'][0]['fromTime']);$this->assertSame('11:00',$s['availability']['blocks'][0]['toTime']);
  $result=app(SalonStore::class)->mutate(fn(&$s)=>CalendarImport::apply($s,[$event],[$choice],'calendar'),false);$this->assertSame(1,$result['skipped']);$this->assertDatabaseCount('deliveries',0);
 }
 public function test_calendar_booking_requires_matching_duration_and_explicit_client_choice_without_notifications():void{
  $event=CalendarImport::event(['id'=>'e2','summary'=>'Tóth Éva','start'=>['dateTime'=>'2036-06-02T10:00:00+02:00'],'end'=>['dateTime'=>'2036-06-02T10:45:00+02:00']]);$choice=['index'=>0,'mode'=>'booking','staff'=>'anna','service'=>'cut','contact'=>true,'name'=>'Tóth Éva','phone'=>'06301234567','email'=>''];
  $result=app(SalonStore::class)->mutate(fn(&$s)=>CalendarImport::apply($s,[$event],[$choice],'calendar'),false);$this->assertSame(1,$result['bookings']);$s=app(SalonStore::class)->read();$this->assertCount(1,$s['clients']);$this->assertNull($s['clients'][0]['guestId']);$this->assertSame('confirmed',$s['bookings'][0]['status']);$this->assertDatabaseCount('deliveries',0);$this->assertDatabaseCount('calendar_tasks',0);
 }
 public function test_calendar_whole_day_and_cancelled_events_are_handled_with_exclusive_end():void{
  $this->assertNull(CalendarImport::event(['status'=>'cancelled']));$event=CalendarImport::event(['id'=>'all','summary'=>'Szabadság','start'=>['date'=>'2036-03-28'],'end'=>['date'=>'2036-03-31']]);$s=app(SalonStore::class)->read();CalendarImport::apply($s,[$event],[['index'=>0,'mode'=>'block','staff'=>'anna','contact'=>false]],'cal');$this->assertCount(3,$s['availability']['blocks']);$this->assertSame('2036-03-30',$s['availability']['blocks'][2]['toDate']);$this->assertTrue($s['availability']['blocks'][2]['allDay']);
 }
 public function test_calendar_oauth_is_read_only_and_state_validation_prevents_external_requests():void{
  config(['contact-import.google_client_id'=>'id','contact-import.google_client_secret'=>'secret']);$r=$this->get('/auth/calendar-import?provider=1')->assertRedirect();parse_str(parse_url($r->headers->get('Location'),PHP_URL_QUERY),$q);$this->assertStringContainsString('calendar.events.readonly',$q['scope']);$this->assertStringNotContainsString('contacts.',$q['scope']);$this->assertSame('S256',$q['code_challenge_method']);$this->get('/auth/calendar-import/callback?state=wrong&code=x')->assertRedirect('/?provider=1&calendarImport=error');Http::assertNothingSent();$this->withSession(['admin'=>false]);$this->get('/auth/calendar-import')->assertForbidden();
 }
 public function test_delayed_mailchimp_send_reconciles_after_twenty_minutes_without_any_second_send():void{
  MarketingConnections::save(1,['engine'=>'mailchimp','apiKey'=>'test-us1','senderName'=>'Teszt','senderEmail'=>'sender@example.com']);$keys=MarketingConnections::get(1);$id='11111111-1111-4111-8111-111111111111';DB::table('marketing_campaigns')->insert(['id'=>$id,'provider_id'=>1,'engine'=>'mailchimp','subject'=>'Delayed','html'=>'<p>x</p>','status'=>'unknown','remote_id'=>'remote','recipients'=>json_encode(['revision'=>$keys['revision']]),'error'=>'A hírlevélküldő elutasította a kérést.','created_at'=>now(),'updated_at'=>now()]);
  Http::fake(['*.api.mailchimp.com/*'=>Http::sequence()->push(['status'=>'save'])->push(['status'=>'sending','emails_sent'=>0])->push(['status'=>'sent','emails_sent'=>1])]);MarketingCampaigns::reconcile();$this->assertSame('unknown',DB::table('marketing_campaigns')->value('status'));$this->travel(20)->minutes();MarketingCampaigns::reconcile();$this->assertSame('submitted',DB::table('marketing_campaigns')->value('status'));$this->assertNull(DB::table('marketing_campaigns')->value('error'));$this->travel(3)->minutes();MarketingCampaigns::reconcile();$this->assertSame('sent',DB::table('marketing_campaigns')->value('status'));Http::assertSentCount(3);Http::assertNotSent(fn($r)=>$r->method()!=='GET');
 }
 public function test_calendar_full_http_flow_previews_then_commits_without_duplicate_or_cross_tenant_access():void{
  config(['contact-import.google_client_id'=>'id','contact-import.google_client_secret'=>'secret']);$date=now()->addDays(3)->toDateString();
  Http::fake(['oauth2.googleapis.com/token'=>Http::response(['access_token'=>'temporary']), 'www.googleapis.com/calendar/v3/users/me/calendarList*'=>Http::response(['items'=>[['id'=>'cal','summary'=>'Vendégek','timeZone'=>'Europe/Budapest']]]),'www.googleapis.com/calendar/v3/calendars/cal/events*'=>Http::response(['items'=>[['id'=>'evt','summary'=>'Vendég','start'=>['dateTime'=>$date.'T10:00:00+01:00'],'end'=>['dateTime'=>$date.'T11:00:00+01:00']]]])]);
  $start=$this->get('/auth/calendar-import');parse_str(parse_url($start->headers->get('Location'),PHP_URL_QUERY),$query);$return=$this->get('/auth/calendar-import/callback?state='.$query['state'].'&code=code')->assertRedirect();parse_str(parse_url($return->headers->get('Location'),PHP_URL_QUERY),$query);$id=$query['calendarImport'];$this->getJson('/api/calendar-import/'.$id)->assertOk()->assertJsonCount(1,'calendars')->assertJsonMissingPath('token');$this->postJson('/api/calendar-import/events',['id'=>$id,'calendar'=>'other','from'=>$date,'to'=>$date])->assertUnprocessable();
  $events=$this->postJson('/api/calendar-import/events',['id'=>$id,'calendar'=>'cal','from'=>$date,'to'=>$date])->assertOk()->assertJsonCount(1,'events')->json();$body=['id'=>$events['id'],'choices'=>[['index'=>0,'mode'=>'block','staff'=>'anna','contact'=>false,'name'=>'','phone'=>'','email'=>'']]];$this->postJson('/api/calendar-import/preview',$body)->assertOk()->assertJsonPath('blocks',1);$this->assertCount(0,app(SalonStore::class)->read()['availability']['blocks']);$this->postJson('/api/calendar-import/commit',$body)->assertOk()->assertJsonPath('blocks',1);$this->postJson('/api/calendar-import/commit',$body)->assertOk()->assertJsonPath('blocks',1);$this->assertCount(1,app(SalonStore::class)->read()['availability']['blocks']);$this->assertDatabaseCount('deliveries',0);
  $this->withSession(['admin'=>false]);$this->postJson('/api/calendar-import/commit',$body)->assertForbidden();
 }
 public function test_same_calendar_event_is_excluded_from_google_busy_but_other_external_events_still_block():void{
  $event=CalendarImport::event(['id'=>'evt','summary'=>'Guest','start'=>['dateTime'=>'2036-06-02T10:00:00+02:00'],'end'=>['dateTime'=>'2036-06-02T10:45:00+02:00']]);$s=app(SalonStore::class)->read();$s['_googleBusy']=['staff:anna'=>[['start'=>strtotime($event['start']),'end'=>strtotime($event['end']),'calendarId'=>'cal','eventId'=>'evt']]];$choice=['index'=>0,'mode'=>'booking','staff'=>'anna','service'=>'cut','contact'=>false,'name'=>'Guest','phone'=>'','email'=>''];CalendarImport::apply($s,[$event],[$choice],'cal');$this->assertCount(1,$s['bookings']);
  $s=app(SalonStore::class)->read();$s['_googleBusy']=['staff:anna'=>[['start'=>strtotime($event['start']),'end'=>strtotime($event['end']),'calendarId'=>'cal','eventId'=>'different']]];$this->expectException(\InvalidArgumentException::class);CalendarImport::apply($s,[$event],[$choice],'cal');
 }

}
